<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use Illuminate\Support\Str;
class CanteenController extends Controller{
private function view(Request $r){abort_unless($r->user()->isSuperAdmin()||$r->user()->hasRole('admin')||$r->user()->hasRole('canteen_manager')||$r->user()->canDo('canteen.view')||$r->user()->canDo('canteen.manage'),403);}
private function manage(Request $r){abort_unless($r->user()->isSuperAdmin()||$r->user()->hasRole('admin')||$r->user()->hasRole('canteen_manager')||$r->user()->canDo('canteen.manage'),403);}
public function index(Request $r){$this->view($r);$today=date('Y-m-d');$stats=['issued'=>DB::table('meal_issues')->where('issue_date',$today)->count(),'breakfast'=>DB::table('meal_issues')->where(['issue_date'=>$today,'meal_type'=>'breakfast'])->count(),'lunch'=>DB::table('meal_issues')->where(['issue_date'=>$today,'meal_type'=>'lunch'])->count(),'benefit'=>DB::table('meal_issues as i')->join('meal_categories as c','c.id','=','i.meal_category_id')->where('i.issue_date',$today)->where('c.benefit',1)->count()];$menus=DB::table('meal_menus')->where('menu_date',$today)->where('active',1)->get();return view('canteen.index',compact('stats','menus','today'));}
public function categories(Request $r){$this->manage($r);$rows=DB::table('meal_categories')->orderBy('name')->get();return view('canteen.categories',compact('rows'));}
public function categoryStore(Request $r){$this->manage($r);$d=$r->validate(['name'=>'required|string|max:255','code'=>'required|string|max:50|unique:meal_categories,code','daily_limit'=>'nullable|numeric|min:0','benefit'=>'nullable|boolean','note'=>'nullable|string|max:3000']);DB::table('meal_categories')->insert($d+['benefit'=>(bool)($d['benefit']??false),'active'=>1,'created_at'=>now(),'updated_at'=>now()]);return back();}
public function menu(Request $r){$this->manage($r);$date=$r->get('date',date('Y-m-d'));$rows=DB::table('meal_menus')->where('menu_date',$date)->orderBy('meal_type')->get();return view('canteen.menu',compact('rows','date'));}
public function menuStore(Request $r){$this->manage($r);$d=$r->validate(['menu_date'=>'required|date','meal_type'=>'required|in:breakfast,lunch,snack,dinner','title'=>'required|string|max:255','composition'=>'nullable|string|max:5000','price'=>'required|numeric|min:0','planned_portions'=>'nullable|integer|min:0']);DB::table('meal_menus')->insert($d+['active'=>1,'created_by'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);return back();}
public function assignments(Request $r){$this->manage($r);$rows=DB::table('student_meal_assignments as a')->join('students as s','s.id','=','a.student_id')->join('meal_categories as c','c.id','=','a.meal_category_id')->leftJoin('study_groups as g','g.id','=','s.current_group_id')->select('a.*','s.last_name','s.first_name','g.name as group_name','c.name as category_name')->orderBy('g.name')->orderBy('s.last_name')->get();$students=DB::table('students')->where('status','active')->orderBy('last_name')->get();$categories=DB::table('meal_categories')->where('active',1)->orderBy('name')->get();return view('canteen.assignments',compact('rows','students','categories'));}
public function assignmentStore(Request $r){$this->manage($r);$d=$r->validate(['student_id'=>'required|exists:students,id','meal_category_id'=>'required|exists:meal_categories,id','valid_from'=>'required|date','valid_to'=>'nullable|date|after_or_equal:valid_from','basis'=>'nullable|string|max:500','document_number'=>'nullable|string|max:100']);DB::table('student_meal_assignments')->insert($d+['created_by'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);return back();}
public function pass(Request $r,$student){$this->manage($r);abort_unless(DB::table('students')->where('id',$student)->exists(),404);DB::table('student_meal_passes')->where(['student_id'=>$student,'status'=>'active'])->update(['status'=>'blocked','blocked_at'=>now(),'updated_at'=>now()]);$token=Str::random(56);DB::table('student_meal_passes')->insert(['student_id'=>$student,'token'=>$token,'status'=>'active','issued_at'=>now(),'issued_by'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);return back()->with('meal_pass_token',$token);}
}